87	function filterEntrypoints( entrypoints ) {
88		if ( ! process.env.ENTRY_LIMIT ) {
89			return entrypoints;
90		}
91	
92		const allowedEntrypoints = process.env.ENTRY_LIMIT.split( ',' );
93	
94		console.warn( '[entrylimit] Limiting build to %s', allowedEntrypoints.join( ', ' ) );
95	
96		const validEntrypoints = allowedEntrypoints.filter( ( ep ) => {
97			if ( entrypoints.hasOwnProperty( ep ) ) {
98				return true;
99			}
100			console.warn( '[entrylimit] Invalid entrypoint: %s. Valid entries are:', ep );
101			Object.keys( entrypoints ).forEach( ( e ) => console.warn( '\t' + e ) );
102			return false;
103		} );
104	
105		if ( validEntrypoints.length === 0 ) {
106			console.warn( '[entrylimit] No matches found!' );
107			throw new Error( 'No valid entrypoints' );
108		}
109	
110		const allowed = {};
111		Object.entries( entrypoints ).forEach( ( [ key, val ] ) => {
112			if ( validEntrypoints.includes( key ) ) {
113				allowed[ key ] = val;
114			}
115		} );
116	
117		return allowed;
118	}
