120	/**
121	 * Given a package name, finds the absolute path for it.
122	 *
123	 * require.resolve() will resolve to the main file of the package, using Node's resolution algorithm to find
124	 * a `package.json` and looking at the field `main`. This function will return the folder that contains `package.json`
125	 * instead of trying to resolve the main file.
126	 *
127	 * Example: `@wordpress/data` may resolve to `/home/myUser/wp-calypso/node_modules/@wordpress/data`.
128	 *
129	 * Note this is not the same as looking for `__dirname+'/node_modules/'+pkgName`, as the package may be in a parent
130	 * `node_modules`
131	 * @param {string} pkgName Name of the package to search for.
132	 */
133	function findPackage( pkgName ) {
134		const fullPath = require.resolve( pkgName );
135		const packagePath = pkgDir.sync( fullPath );
136		return packagePath;
137	}
