8	import FeedError from 'calypso/reader/feed-error';
9	import StreamComponent from 'calypso/reader/following/main';
10	import { isAutomatticTeamMember } from 'calypso/reader/lib/teams';
11	import { recordTrack } from 'calypso/reader/stats';
12	import { isUserLoggedIn } from 'calypso/state/current-user/selectors';
13	import { getLastPath } from 'calypso/state/reader-ui/selectors';
14	import { toggleReaderSidebarFollowing } from 'calypso/state/reader-ui/sidebar/actions';
15	import { isFollowingOpen } from 'calypso/state/reader-ui/sidebar/selectors';
16	import getCurrentRoute from 'calypso/state/selectors/get-current-route';
17	import { getReaderTeams } from 'calypso/state/teams/selectors';
18	import { getSection } from 'calypso/state/ui/selectors';
19	import { setupRedirectRoutes } from 'calypso/utils';
20	import {
21		trackPageLoad,
22		trackUpdatesLoaded,
23		trackScrollPage,
24		setPageTitle,
25		getStartDate,
26	} from './controller-helper';
27	
28	const analyticsPageTitle = 'Reader';
29	
30	function renderFeedError( context, next ) {
31		context.primary = createElement( FeedError );
32		next();
33	}
34	
35	export function sidebar( context, next ) {
36		const state = context.store.getState();
37		if ( isUserLoggedIn( state ) ) {
38			context.secondary = (
39				<AsyncLoad require="calypso/reader/sidebar" path={ context.path } placeholder={ null } />
40			);
41		}
42	
43		next();
44	}
45	
46	export function unmountSidebar( context, next ) {
47		next();
48	}
49	
50	export function following( context, next ) {
51		const basePath = sectionify( context.path );
52		const fullAnalyticsPageTitle = analyticsPageTitle + ' > Following';
53		const mcKey = 'following';
54		const startDate = getStartDate( context );
55	
56		const state = context.store.getState();
57		// only for a8c for now
58		if ( isAutomatticTeamMember( getReaderTeams( state ) ) ) {
59			// select last reader path if available, otherwise just open following
60			const currentSection = getSection( state );
61			const lastPath = getLastPath( state );
62	
63			if ( lastPath && lastPath !== '/reader' && currentSection.name !== 'reader' ) {
64				return page.redirect( lastPath );
65			}
66	
67			// if we have no last path, default to Following/All and expand following
68			const isOpen = isFollowingOpen( state );
69			if ( ! isOpen ) {
70				context.store.dispatch( toggleReaderSidebarFollowing() );
71			}
72		}
73	
74		trackPageLoad( basePath, fullAnalyticsPageTitle, mcKey );
75		recordTrack(
76			'calypso_reader_following_loaded',
77			{},
78			{ pathnameOverride: getCurrentRoute( state ) }
79		);
80	
81		setPageTitle( context, i18n.translate( 'Following' ) );
82	
83		// warn: don't async load this only. we need it to keep feed-post-store in the reader bundle
84		context.primary = createElement( StreamComponent, {
85			key: 'following',
86			listName: i18n.translate( 'Followed Sites' ),
87			streamKey: 'following',
88			startDate,
89			recsStreamKey: 'custom_recs_posts_with_images',
90			trackScrollPage: trackScrollPage.bind(
91				null,
92				basePath,
93				fullAnalyticsPageTitle,
94				analyticsPageTitle,
95				mcKey
96			),
97			onUpdatesShown: trackUpdatesLoaded.bind( null, mcKey ),
98			feedId: context.params.feed_id,
99		} );
100		next();
101	}
102	
103	export function feedDiscovery( context, next ) {
104		if ( ! context.params.feed_id.match( /^\d+$/ ) ) {
105			const url = context.params.feed_id;
106			context.queryClient
107				.fetchQuery( {
108					queryKey: [ 'feed-discovery', url ],
109					queryFn: () =>
110						wpcom.req.get( '/read/feed', { url } ).then( ( res ) => res.feeds[ 0 ].feed_ID ),
111					meta: { persist: false },
