261	export async function blogDiscoveryByFeedId( context, next ) {
262		const { blog, feed_id } = context.params;
263	
264		// If we have already had blog or we don't have feed_id, call `next()` immediately
265		if ( blog || ! feed_id ) {
266			next();
267			return;
268		}
269	
270		// Query the site by feed_id and inject to the context params so that calypso can get correct site
271		// after redirecting the user to log-in page
272		context.queryClient
273			.fetchQuery( {
274				queryKey: [ '/read/feed/', feed_id ],
275				queryFn: () => wpcom.req.get( `/read/feed/${ feed_id }` ).then( ( res ) => res.blog_ID ),
276				meta: { persist: false },
277			} )
278			.then( ( blog_id ) => {
279				context.params.blog_id = blog_id;
280				next();
281			} )
282			.catch( () => {
283				renderFeedError( context, next );
284			} );
285	}
