11	export async function initializeCurrentUser() {
12		let skipBootstrap = false;
13	
14		if ( isSupportUserSession() ) {
15			// boot the support session and skip the user bootstrap: the server sent the unwanted
16			// user info there (me) instead of the target SU user.
17			supportUserBoot();
18			skipBootstrap = true;
19		}
20	
21		if ( isSupportNextSession() ) {
22			// boot the support session and proceed with user bootstrap (unlike the SupportUserSession,
23			// the initial GET request includes the right cookies and header and returns a server-generated
24			// page with the right window.currentUser value)
25			supportNextBoot();
26		}
27	
28		if ( ! skipBootstrap && config.isEnabled( 'wpcom-user-bootstrap' ) ) {
29			if ( window.currentUser ) {
30				return window.currentUser;
31			}
32			return false;
33		}
34	
35		let userData;
36		try {
37			userData = await rawCurrentUserFetch();
38		} catch ( error ) {
39			if ( error.error !== 'authorization_required' ) {
40				// eslint-disable-next-line no-console
41				console.error( 'Failed to fetch the user from /me endpoint:', error );
42			}
43		}
44	
45		if ( ! userData ) {
46			return false;
47		}
48	
49		return filterUserObject( userData );
50	}
