52			const path = parsed.pathname + parsed.search || null;
53			context.prevPath = path === context.path ? false : path;
54			context.query = Object.fromEntries( parsed.searchParams.entries() );
55	
56			context.hashstring = ( parsed.hash && parsed.hash.substring( 1 ) ) || '';
57			// set `context.hash` (we have to parse manually)
58			if ( context.hashstring ) {
59				try {
60					context.hash = Object.fromEntries(
61						new globalThis.URLSearchParams( context.hashstring ).entries()
62					);
63				} catch ( e ) {
64					debug( 'failed to query-string parse `location.hash`', e );
65					context.hash = {};
66				}
67			} else {
68				context.hash = {};
69			}
70	
71			context.store = reduxStore;
72			context.queryClient = reactQueryClient;
73	
74			// client version of the isomorphic method for redirecting to another page
75			context.redirect = ( httpCode, newUrl = null ) => {
76				if ( isNaN( httpCode ) && ! newUrl ) {
77					newUrl = httpCode;
78				}
79	
80				return page.replace( newUrl, context.state, false, false );
81			};
82	
83			// Break routing and do full load for logout link in /me
84			if ( context.pathname === '/wp-login.php' ) {
85				window.location.href = context.path;
86				return;
87			}
88	
89			// Some paths live outside of Calypso and should be opened separately
90			// Examples: /support, /forums
91			if ( isOutsideCalypso( context.pathname ) ) {
92				window.location.href = context.path;
93				return;
94			}
95	
96			next();
97		} );
98	
99		page.exit( '*', ( context, next ) => {
100			context.store = reduxStore;
101			context.queryClient = reactQueryClient;
102	
103			next();
104		} );
105	};
