117		const flags = new URLSearchParams( window.location.search ).get( 'flags' );
118		if ( ! flags ) {
119			return;
120		}
121	
122		const oauthFlag = flags.split( ',' ).find( ( flag ) => /^[+-]?oauth$/.test( flag ) );
123		if ( ! oauthFlag ) {
124			return;
125		}
