134		);
135		redirectUri.search = new URLSearchParams( {
136			next: window.location.pathname + window.location.search,
137		} ).toString();
138	
139		const authUri = new URL( 'https://public-api.wordpress.com/oauth2/authorize' );
140		authUri.search = new URLSearchParams( {
141			response_type: 'token',
142			client_id: config( 'oauth_client_id' ),
143			redirect_uri: redirectUri.toString(),
144			scope: 'global',
145			blog_id: 0,
146		} ).toString();
