1	import path from 'path';
2	import chalk from 'chalk';
3	import cookieParser from 'cookie-parser';
4	import express from 'express';
5	import userAgent from 'express-useragent';
6	import { createProxyMiddleware } from 'http-proxy-middleware';
7	import api from 'calypso/server/api';
8	import config from 'calypso/server/config';
9	import analytics from 'calypso/server/lib/analytics';
10	import loggerMiddleware from 'calypso/server/middleware/logger';
11	import pages from 'calypso/server/pages';
12	import pwa from 'calypso/server/pwa';
13	
14	/**
15	 * Returns the server HTTP request handler "app".
16	 * @returns {Object} The express app
17	 */
18	export default function setup() {
19		const app = express();
20	
21		// for nginx
22		app.enable( 'trust proxy' );
23	
24		app.use( cookieParser() );
25		app.use( userAgent.express() );
26		app.use( loggerMiddleware() );
27	
28		if ( process.env.USE_SERVER_PROFILER === 'true' ) {
29			// TODO: Re-enable this middleware once `v8-profiler-next` adds support for Node.js 22
30			// app.use( require( 'calypso/server/middleware/profiler' )() );
31			console.warn(
32				'Server profiling is temporarily disabled until `v8-profiler-next` adds support for Node.js 22.'
33			);
34		}
35	
36		if ( 'development' === process.env.NODE_ENV ) {
37			require( 'calypso/server/bundler' )( app );
38	
39			// When mocking WordPress.com to point locally, wordpress.com/wp-login.php will hit Calypso creating an infinite loop.
40			// redirect traffic to de.wordpress.com to hit the real backend and prevent a loop.
41			// `de.wordpress.com` accepts POST requests to `/wp-login.php` exactly like `wordpress.com`.
42			if ( process.env.MOCK_WORDPRESSDOTCOM === '1' ) {
43				app.use(
44					'/wp-login.php',
45					createProxyMiddleware( { target: 'https://de.wordpress.com/wp-login.php' } )
46				);
47			}
48	
49			if ( config.isEnabled( 'wpcom-user-bootstrap' ) ) {
50				if ( config( 'wordpress_logged_in_cookie' ) ) {
51					const username = config( 'wordpress_logged_in_cookie' ).split( '%7C' )[ 0 ];
52					console.info( chalk.cyan( '\nYour logged in cookie set to user: ' + username ) );
53	
54					app.use( function ( req, res, next ) {
55						if ( ! req.cookies.wordpress_logged_in ) {
56							req.cookies.wordpress_logged_in = config( 'wordpress_logged_in_cookie' );
57						}
58						next();
59					} );
60				} else {
61					console.info(
62						chalk.red(
63							'\nYou need to set `wordpress_logged_in_cookie` in secrets.json' +
64								' for wpcom-user-bootstrap to work in development.'
65						)
66					);
67				}
68	
69				// Use try/catch because config() will throw for missing keys in development mode,
70				// and we don't want an exception if `support_session_id_cookie` is undefined.
71				try {
72					const supportSessionIdCookie = config( 'support_session_id_cookie' );
73					if ( supportSessionIdCookie ) {
74						app.use( function ( req, res, next ) {
75							if ( ! req.cookies.support_session_id ) {
76								req.cookies.support_session_id = supportSessionIdCookie;
77							}
78							next();
79						} );
80					}
81				} catch ( e ) {}
82			}
83		}
84	
85		app.use( pwa() );
86	
87		// attach the static file server to serve the `public` dir
88		app.use( '/calypso', express.static( path.resolve( __dirname, '..', '..', '..', 'public' ) ) );
89	
90		// loaded when we detect stats blockers - see lib/analytics/index.js
91		app.get( '/nostats.js', function ( request, response ) {
92			analytics.tracks.recordEvent(
93				'calypso_stats_blocked',
94				{
95					do_not_track: request.headers.dnt,
96				},
97				request
98			);
99			response.setHeader( 'content-type', 'application/javascript' );
100			response.end( "console.log('Stats are disabled');" );
101		} );
102	
103		if ( config.isEnabled( 'devdocs' ) ) {
104			app.use( require( 'calypso/server/devdocs' ).default() );
105		}
106	
107		app.use( api() );
108	
109		// attach the pages module
110		app.use( pages() );
111	
112		return app;
113	}
