17	function middleware( app ) {
18		const compiler = webpack( webpackConfig );
19		const callbacks = [];
20		let built = false;
21		let beforeFirstCompile = true;
22	
23		app.set( 'compiler', compiler );
24	
25		if ( shouldProfile ) {
26			new compiler.webpack.ProgressPlugin( { profile: true } ).apply( compiler );
27		}
28	
29		// In development environment we need to wait for initial webpack compile
30		// to finish and execute the build-languages script if translation chunks
31		// feature is enabled.
32		if ( shouldBuildChunksMap ) {
33			callbacks.push( () => {
34				execSync( 'yarn run build-languages' );
