36		}
37	
38		compiler.hooks.done.tap( 'Calypso', function () {
39			built = true;
40	
41			// Dequeue and call request handlers
42			while ( callbacks.length > 0 ) {
43				callbacks.shift()();
44			}
45	
46			// In order to show our message *after* webpack's "bundle is now VALID"
47			// we need to skip two event loop ticks, because webpack's callback is
48			// also hooked on the "done" event, it calls nextTick to print the message
49			// and runs before our callback (calls app.use earlier in the code)
50			process.nextTick( function () {
51				process.nextTick( function () {
52					if ( beforeFirstCompile ) {
53						beforeFirstCompile = false;
54						console.info(
55							chalk.cyan(
56								`\nReady! You can load ${ protocol }://${ host }:${ port }/ now. Have fun!`
57							)
58						);
59					} else {
60						console.info( chalk.cyan( '\nReady! All assets are re-compiled. Have fun!' ) );
61					}
62				} );
63			} );
64		} );
65	
66		function waitForCompiler( request, response, next ) {
67			if ( built ) {
68				return next();
69			}
70	
71			console.info(
72				`Compiling assets... Wait until you see Ready! and then try ${ protocol }://${ host }:${ port }/ again.`
73			);
74	
75			// a special message for newcomers, because seeing a blank page is confusing
76			if ( request.url === '/' ) {
77				response.send( `
78					<head>
79						<meta http-equiv="refresh" content="5">
80					</head>
81					<body>
82						<h1>Welcome to Calypso!</h1>
83						<p>
84							Please wait until webpack has finished compiling and you see
85							<code style="font-size: 1.2em; color: blue; font-weight: bold;">READY!</code> in
86							the server console. This page should then refresh automatically. If it hasn&rsquo;t, hit <em>Refresh</em>.
87						</p>
88						<p>
89							In the meantime, try to follow all the emotions of the allmoji:
90							<img src="https://emoji.slack-edge.com/T024FN1V2/allmoji/15b93529a828705f.gif"
91								width="36" style="vertical-align: middle;">
92					</body>
