96				callbacks.push( waitForCompiler.bind( null, request, response, next ) );
97			}
98		}
99	
100		app.use( waitForCompiler );
101		app.use( webpackMiddleware( compiler ) );
102		app.use( hotMiddleware( compiler ) );
103	}
104	
