3	/**
4	 * Add the post URL from a duplicate x-post to an existing post key
5	 * @param {Object} postKey1 First post key
6	 * @param {Object} postKey2 Second (duplicate) post key
7	 * @returns {Object} Post key
8	 */
9	export const addDuplicateXPostToPostKey = ( postKey1, postKey2 ) => {
10		return {
11			...postKey1,
12			// Add the URL from the second post key
13			xPostUrls: Array.isArray( postKey1.xPostUrls )
14				? [ ...postKey1.xPostUrls, postKey2.url ]
15				: [ postKey2.url ],
16		};
17	};
18	
19	/**
20	 * Combine adjacent x-posts that refer to the same original post
21	 * @param {Array} postKeys Array of post key objects
22	 * @returns {Array} Array of post key objects
23	 */
24	export const combineXPosts = ( postKeys ) =>
25		postKeys.reduce( ( accumulator, postKey ) => {
26			const lastPostKey = accumulator[ accumulator.length - 1 ];
27			if ( sameXPost( lastPostKey, postKey ) ) {
28				accumulator[ accumulator.length - 1 ] = addDuplicateXPostToPostKey( lastPostKey, postKey );
29			} else {
30				accumulator.push( postKey );
31			}
32			return accumulator;
33		}, [] );
