20	export function showSelectedPost( { postKey, comments }: ShowSelectedPostArgs ) {
21		return ( _dispatch: Dispatch, getState: () => AppState ): Window | null | void => {
22			if ( ! postKey ) {
23				return;
24			}
25	
26			// rec block
27			if ( postKey.isRecommendationBlock ) {
28				return;
29			}
30	
31			const post = getPostByKey( getState(), postKey );
32	
33			const isLoggedIn = isUserLoggedIn( getState() );
34	
35			if ( ! isLoggedIn ) {
36				return window.open( post.URL + ( comments ? '#comments' : '' ), '_blank' );
37			}
38	
39			if ( isXPost( post ) ) {
40				return showFullXPost( XPostHelper.getXPostMetadata( post ) as ShowFullXPostArgs );
41			}
42	
43			// normal
44			let mappedPost;
45			if ( postKey.feedId ) {
46				mappedPost = {
47					feed_ID: postKey.feedId,
48					feed_item_ID: postKey.postId,
49				};
50			} else {
51				mappedPost = {
52					site_ID: postKey.blogId,
53					ID: postKey.postId,
54				};
55			}
