122	/**
123	 * Wrapper around `safeImageUrl` of '@automattic/calypso-url' to be used in the reader.
124	 * There are some places in the reader where we need to show images from trusted hosts without running them through Photon.
125	 */
126	export function getSafeImageUrlForReader( url: string ): string {
127		const parsedUrl = getUrlParts( url );
128		// Hosts that are trusted to serve images.
129		const TRUSTED_HOSTS = [ 'www.redditstatic.com' ];
130	
131		if ( TRUSTED_HOSTS.includes( parsedUrl.hostname ) ) {
132			return url;
133		}
