140	export function getUrlQuerySearchTerm( pathname: string = '' ): string {
141		// If a pathname is provided, make sure that we get search key only for the given page. Prevents situation where we get search key from a different page.
142		if ( pathname && location.pathname !== pathname ) {
143			return '';
144		}
145	
146		const queryArgs = getQueryArgs( window.location.href );
147		return ( queryArgs[ SEARCH_QUERY_PARAM ] as string ) ?? '';
148	}
