150	export function setUrlQuery( key: string, value: string, pathname: string = '' ): void {
151		// If a pathname is provided, make sure that we set search key only for the given page. Prevents situation where we set search key for a different page.
152		if ( pathname && location.pathname !== pathname ) {
153			return;
154		}
155	
156		const path = window.location.pathname + window.location.search;
157		const nextPath = ! value
158			? removeQueryArgs( path, key )
159			: addQueryArgs( path, { [ key ]: value } );
160	
161		// Only trigger a page show when path has changed.
162		if ( nextPath !== path ) {
163			page.replace( nextPath );
164		}
165	}
