7	const TOKEN_NAME = 'wpcom_token';
8	const MAX_AGE = 365 * 24 * 60 * 60 * 1000; // How long to store the OAuth cookie
9	
10	export function getToken() {
11		const cookies = cookie.parse( document.cookie );
12	
13		if ( typeof cookies[ TOKEN_NAME ] !== 'undefined' ) {
14			return cookies[ TOKEN_NAME ];
15		}
16	
17		const token = store.get( TOKEN_NAME );
18	
19		if ( token ) {
20			return token;
21		}
22	
23		return false;
24	}
25	
26	export function setToken( token ) {
27		// TODO: Support secure cookies if this is ever used outside of the desktop app
28		document.cookie = cookie.serialize( TOKEN_NAME, token, { maxAge: MAX_AGE } );
29	}
30	
31	export function clearToken() {
32		const cookies = cookie.parse( document.cookie );
33	
34		if ( typeof cookies[ TOKEN_NAME ] !== 'undefined' ) {
35			document.cookie = cookie.serialize( TOKEN_NAME, false, { maxAge: -1 } );
36		}
37	}
