22	/**
23	 * Requests the current user for user bootstrap.
24	 * @param {Object} request An Express request.
25	 * @returns {Promise<Object>} A promise for a user object.
26	 */
27	export default async function getBootstrappedUser( request ) {
28		const authCookieValue = request.cookies[ AUTH_COOKIE_NAME ];
29		const geoCountry = request.get( 'x-geoip-country-code' ) || '';
30		const supportSessionHeader = request.get( 'x-support-session' );
31		const supportSessionCookie = request.cookies[ SUPPORT_SESSION_COOKIE_NAME ];
32	
33		if ( ! authCookieValue ) {
34			throw new Error( 'Cannot bootstrap without an auth cookie' );
35		}
36	
37		if ( supportSessionHeader && supportSessionCookie ) {
38			// We don't expect to see a support session header and cookie at the same time.
39			// They are separate support session auth options.
40			throw new Error(
41				'Cannot bootstrap with both a support session header and support session cookie.'
42			);
43		}
44	
45		const decodedAuthCookieValue = decodeURIComponent( authCookieValue );
46	
47		// create HTTP Request object
48		const req = superagent.get( url );
49		req.set( 'User-Agent', 'WordPress.com Calypso' );
50		req.set( 'X-Forwarded-GeoIP-Country-Code', geoCountry );
51	
52		const cookies = [ `${ AUTH_COOKIE_NAME }=${ decodedAuthCookieValue }` ];
53		if ( supportSessionCookie ) {
54			cookies.push( `${ SUPPORT_SESSION_COOKIE_NAME }=${ supportSessionCookie }` );
55		}
56		req.set( 'Cookie', cookies.join( '; ' ) );
57	
58		if ( supportSessionHeader ) {
59			const supportSessionApiKey = getSupportSessionApiKey();
60			if ( typeof supportSessionApiKey !== 'string' ) {
61				throw new Error(
62					'Unable to bootstrap user because of invalid SUPPORT SESSION API key in secrets.json'
63				);
64			}
65	
66			const hmac = crypto.createHmac( 'md5', supportSessionApiKey );
67			hmac.update( supportSessionHeader );
68			const hash = hmac.digest( 'hex' );
69	
70			req.set( 'Authorization', `X-WPCALYPSO-SUPPORT-SESSION ${ hash }` );
71			req.set( 'x-support-session', supportSessionHeader );
72		} else {
73			const apiKey = getApiKey();
74	
75			if ( typeof apiKey !== 'string' ) {
76				throw new Error( 'Unable to bootstrap user because of invalid API key in secrets.json' );
77			}
78	
79			const hmac = crypto.createHmac( 'md5', apiKey );
80			hmac.update( decodedAuthCookieValue );
81			const hash = hmac.digest( 'hex' );
82	
83			req.set( 'Authorization', 'X-WPCALYPSO ' + hash );
84		}
