39		const enabledFeatures = opts.enabledFeatures ? opts.enabledFeatures.split( ',' ) : [];
40		const disabledFeatures = opts.disabledFeatures ? opts.disabledFeatures.split( ',' ) : [];
41	
42		configFiles.forEach( function ( file ) {
43			// merge the objects in `features` field, and do a simple assignment for other fields
44			assignWith( data, getDataFromFile( file ), ( objValue, srcValue, key ) =>
45				key === 'features' ? { ...objValue, ...srcValue } : undefined
46			);
47		} );
48	
49		if ( data.hasOwnProperty( 'features' ) ) {
50			enabledFeatures.forEach( function ( feature ) {
51				data.features[ feature ] = true;
52				debug( 'overriding feature %s to true', feature );
53			} );
54			disabledFeatures.forEach( function ( feature ) {
55				data.features[ feature ] = false;
56				debug( 'overriding feature %s to false', feature );
57			} );
58		}
59	
60		// `protocol`, `hostname` and `port` config values can be overridden by env variables
61		data.protocol = process.env.PROTOCOL || data.protocol;
62		data.hostname = process.env.HOST || data.hostname;
63		data.port = process.env.PORT || data.port;
64	
65		const serverData = Object.assign( {}, data, getDataFromFile( secretsPath ) );
66		const clientData = Object.assign( {}, data );
67	
68		// Optionally override API secrets with env values, only for server data
69		serverData.wpcom_calypso_rest_api_key =
70			process.env.WPCOM_CALYPSO_REST_API_KEY ?? serverData.wpcom_calypso_rest_api_key;
71		serverData.wpcom_calypso_support_session_rest_api_key =
72			process.env.WPCOM_CALYPSO_SUPPORT_SESSION_REST_API_KEY ??
73			serverData.wpcom_calypso_support_session_rest_api_key;
74	
75		if (
76			data.features &&
77			data.features[ 'wpcom-user-bootstrap' ] &&
78			! serverData.wpcom_calypso_rest_api_key
79		) {
80			console.error(
81				'Disabling server-side user-bootstrapping because of missing wpcom_calypso_rest_api_key'
82			);
83			serverData.features[ 'wpcom-user-bootstrap' ] = false;
84			clientData.features[ 'wpcom-user-bootstrap' ] = false;
85		}
86	
87		return { serverData, clientData };
88	};
