3	// Breakpoint Mixin
4	// This has been deprecated. New breakpoints should be created using Gutenberg breakpoints:
5	// https://github.com/WordPress/gutenberg/blob/0f1f5e75408705f0ec014f5d2ea3d9fcc8a97817/packages/base-styles/_mixins.scss
6	//
7	// See https://wpcalypso.wordpress.com/devdocs/docs/coding-guidelines/css.md#media-queries
8	// ==========================================================================
9	
10	$breakpoints: 480px, 660px, 800px, 960px, 1040px, 1280px, 1400px; // Think very carefully before adding a new breakpoint
11	
12	@mixin breakpoint-deprecated( $sizes... ) {
13		@each $size in $sizes {
14			@if type-of( $size ) == string {
15				$approved-value: 0;
16				@each $breakpoint in $breakpoints {
17					$and-larger: ">" + $breakpoint;
18					$and-smaller: "<" + $breakpoint;
19	
20					@if $size == $and-smaller {
21						$approved-value: 1;
22						@media (max-width: $breakpoint) {
23							@content;
24						}
25					} @else {
26						@if $size == $and-larger {
27							$approved-value: 2;
28							@media (min-width: $breakpoint + 1) {
29								@content;
30							}
31						} @else {
32							@each $breakpoint-end in $breakpoints {
33								$range: $breakpoint + "-" + $breakpoint-end;
34								@if $size == $range {
35									$approved-value: 3;
36									@media (min-width: $breakpoint + 1) and (max-width: $breakpoint-end) {
37										@content;
38									}
39								}
40							}
41						}
42					}
43				}
44				@if $approved-value == 0 {
45					$sizes: "";
46					@each $breakpoint in $breakpoints {
47						$sizes: $sizes + " " + $breakpoint;
48					}
49					// TODO - change this to use @error, when it is supported by node-sass
50					@warn "ERROR in breakpoint-deprecated( #{ $size } ): You can only use these sizes[ #{$sizes} ] using the following syntax [ <#{ nth( $breakpoints, 1 ) } >#{ nth( $breakpoints, 1 ) } #{ nth( $breakpoints, 1 ) }-#{ nth( $breakpoints, 2 ) } ]";
51				}
52			} @else {
53				$sizes: "";
54				@each $breakpoint in $breakpoints {
55					$sizes: $sizes + " " + $breakpoint;
56				}
57				// TODO - change this to use @error, when it is supported by node-sass
58				@warn "ERROR in breakpoint-deprecated( #{ $size } ): Please wrap the breakpoint $size in parenthesis. You can use these sizes[ #{$sizes} ] using the following syntax [ <#{ nth( $breakpoints, 1 ) } >#{ nth( $breakpoints, 1 ) } #{ nth( $breakpoints, 1 ) }-#{ nth( $breakpoints, 2 ) } ]";
59			}
60		}
61	}
