364		if ( ! api ) {
365			warn( `Unable to determine api path for ${ streamKey }` );
366			return;
367		}
368	
369		const {
370			apiVersion = '1.2',
371			path,
372			query = defaultQueryFn,
373			pollQuery = getQueryStringForPoll,
374		} = api;
375	
376		const algorithm = getAlgorithmForStream( streamKey )
377			? { algorithm: getAlgorithmForStream( streamKey ) }
378			: {};
379	
380		const fetchCount = pageHandle ? PER_FETCH : INITIAL_FETCH;
381		// eslint-disable-next-line no-extra-boolean-cast
382		let number;
383		if ( page ) {
384			number = perPage;
385		} else {
386			number = gap ? PER_GAP : fetchCount;
387		}
388	
389		// Set lang to the localeSlug if it is provided, otherwise use the default locale
390		// There is a race condition in switchLocale when retrieving the language file
391		// The stream request can occur before the language file is loaded, so we need a way to explicitly set the lang in the request
392		const lang = localeSlug || i18n.getLocaleSlug();
393		const commonQueryParams = { ...algorithm, feed_id: feedId };
394	
395		return http( {
396			method: 'GET',
397			path: path( { ...action.payload } ),
398			apiVersion,
399			apiNamespace: api.apiNamespace ?? null,
400			query: isPoll
401				? pollQuery( [], commonQueryParams )
402				: query( { ...commonQueryParams, ...pageHandle, number, lang, page }, action.payload ),
403			onSuccess: action,
404			onFailure: action,
405		} );
406	}
