412		} else if ( includes( streamType, 'rec' ) ) {
413			const offset = get( action, 'payload.pageHandle.offset', 0 ) + PER_FETCH;
414			return { offset };
415		} else if ( next_page || ( meta && meta.next_page ) ) {
416			// sites give page handles nested within the meta key
417			return { page_handle: next_page || meta.next_page };
418		} else if ( date_range && date_range.after ) {
419			// feeds use date_range. no next_page handles here
420			// search api will give you a date_range but for relevance search it will have before/after=null
421			// and offsets must be used
422			const { after } = date_range;
423			return { before: after };
424		}
425		return null;
426	}
