439		// If the payload has posts, then this stream is intended to be a post stream
440		// If the payload has sites, then we need to extract the posts from the sites and update the post stream
441		// If the payload has cards, then we need to extract the posts from the cards and update the post stream
442		// Cards also contain recommended sites which we need to extract and update the sites stream
443		if ( posts ) {
444			const streamData = createStreamDataFromPosts( posts, dateProperty );
445			streamItems = streamData.streamItems;
446			streamPosts = streamData.streamPosts;
447		} else if ( sites ) {
448			const streamData = createStreamDataFromSites( sites, dateProperty );
449			streamItems = streamData.streamItems;
450			streamPosts = streamData.streamPosts;
