1	import moment from 'moment';
2	import { keysAreEqual } from 'calypso/reader/post-key';
3	import {
4		READER_STREAMS_PAGE_REQUEST,
5		READER_STREAMS_PAGE_RECEIVE,
6		READER_STREAMS_PAGINATED_REQUEST,
7		READER_STREAMS_SELECT_ITEM,
8		READER_STREAMS_UPDATES_RECEIVE,
9		READER_STREAMS_SELECT_NEXT_ITEM,
10		READER_STREAMS_SELECT_PREV_ITEM,
11		READER_STREAMS_SHOW_UPDATES,
12		READER_DISMISS_POST,
13		READER_STREAMS_CLEAR,
14		READER_STREAMS_NEW_POST_RECEIVE,
15		READER_STREAMS_REMOVE_ITEM,
16	} from 'calypso/state/reader/action-types';
17	import { keyedReducer, combineReducers } from 'calypso/state/utils';
18	import { combineXPosts } from './utils';
19	
20	const takeWhile = ( array, predicate ) => {
21		const [ x, ...xs ] = array;
22	
23		if ( array.length > 0 && predicate( x ) ) {
24			return [ x, ...takeWhile( xs, predicate ) ];
25		}
26		return [];
27	};
28	
29	const takeRightWhile = ( array, predicate ) => {
30		return takeWhile( [ ...array ].reverse(), predicate );
31	};
32	
33	/*
34	 * Contains a list of post-keys representing the items of a stream.
35	 */
36	export const items = ( state = [], action ) => {
37		let streamItems;
38		let gap;
39		let newState;
40		let newXPosts;
41		let perPage;
42		let page;
43		let streamKey;
44	
45		switch ( action.type ) {
46			case READER_STREAMS_PAGE_RECEIVE:
47				gap = action.payload.gap;
48				streamItems = action.payload.streamItems;
49				perPage = action.payload.perPage;
50				page = action.payload.page;
51				streamKey = action.payload.streamKey;
52	
53				if ( ! Array.isArray( streamItems ) ) {
54					return state;
55				}
56	
57				// For the Recent feeds, we need to pad the stream with empty items
58				// for the DataViews pagination to work correctly
59				// see Automattic/loop#238
60				if ( streamKey?.startsWith( 'recent' ) && streamItems.length > 0 && perPage && page > 1 ) {
61					// Calculate where new items should start
62					const startIndex = ( page - 1 ) * perPage;
63					const existingLength = state.length;
64					const paddingNeeded = startIndex - existingLength;
65	
66					// Case 1: Need to add padding before new items
67					if ( paddingNeeded > 0 ) {
68						const paddingItems = Array( paddingNeeded )
69							.fill( undefined )
70							.map( ( _, index ) => ( {
71								isPadding: true,
72								postId: `padding-${ index }`,
73							} ) );
74	
75						return combineXPosts( [ ...state, ...paddingItems, ...streamItems ] );
76					}
77	
78					// Case 2: Replace existing items at correct index
79					const updatedState = [ ...state ];
80					streamItems.forEach( ( item, index ) => {
81						updatedState[ startIndex + index ] = item;
82					} );
83	
84					return combineXPosts( updatedState );
85				}
86	
87				if ( gap ) {
88					const beforeGap = takeWhile( state, ( postKey ) => ! keysAreEqual( postKey, gap ) );
89					const afterGap = takeRightWhile( state, ( postKey ) => ! keysAreEqual( postKey, gap ) );
90	
91					// after query param is inclusive, so we need to drop duplicate post
92					if ( keysAreEqual( streamItems[ streamItems.length - 1 ], afterGap[ 0 ] ) ) {
93						streamItems.pop();
94					}
95	
96					// gap was empty
97					if ( streamItems.length === 0 ) {
98						return [ ...beforeGap, ...afterGap ];
99					}
100	
101					// create a new gap if we still need one
102					let nextGap = [];
103					const from = gap.from;
104					const to = moment( streamItems[ streamItems.length - 1 ]?.date );
105					if ( ! from.isSame( to ) ) {
106						nextGap = [ { isGap: true, from, to } ];
107					}
108	
109					return combineXPosts( [ ...beforeGap, ...streamItems, ...nextGap, ...afterGap ] );
110				}
111	
112				// add the `streamItems` to state, but only ones that aren't already there
113				newState = streamItems.reduce( ( accuState, streamItem ) => {
114					const isNew = ! accuState.some( ( accuItem ) => keysAreEqual( accuItem, streamItem ) );
115					return isNew ? [ ...accuState, streamItem ] : accuState;
116				}, state );
117	
118				// Find any x-posts
119				newXPosts = streamItems.filter( ( postKey ) => postKey.xPostMetadata );
120	
121				if ( ! newXPosts ) {
122					return newState;
123				}
124	
125				// Filter out duplicate x-posts
126				return combineXPosts( newState );
127			case READER_STREAMS_NEW_POST_RECEIVE: {
128				const newPost = {
129					...action.payload.postData,
130					isSynthetic: true,
131				};
132				return [ newPost, ...state ];
133			}
134			case READER_STREAMS_SHOW_UPDATES:
135				return combineXPosts( [ ...action.payload.items, ...state ] );
136			case READER_DISMISS_POST: {
137				const postKey = action.payload.postKey;
138				const indexToRemove = state.findIndex( ( item ) => keysAreEqual( item, postKey ) );
139	
140				if ( indexToRemove === -1 ) {
141					return state;
142				}
143	
144				const updatedState = [ ...state ];
145				updatedState[ indexToRemove ] = updatedState.pop(); // set the dismissed post location to the last item from the recs stream
146				return updatedState;
147			}
148			case READER_STREAMS_REMOVE_ITEM: {
149				const postKey = action.payload.postKey;
150				return state.filter( ( item ) => ! keysAreEqual( item, postKey ) );
151			}
152			case READER_STREAMS_CLEAR:
153				return [];
154		}
155		return state;
156	};
157	
158	export const PENDING_ITEMS_DEFAULT = { lastUpdated: null, items: [] };
159	/*
160	 * Contains new items in the stream that we've learned about since initial render
161	 * but don't want to display just yet.
162	 * This is the data backing the orange "${number} new posts" pill.
163	 */
164	export const pendingItems = ( state = PENDING_ITEMS_DEFAULT, action ) => {
165		let streamItems;
166		let maxDate;
167		let minDate;
168		let newItems;
169		let newXPosts;
170		switch ( action.type ) {
171			case READER_STREAMS_PAGE_RECEIVE:
172				streamItems = action.payload.streamItems;
173				if ( streamItems.length === 0 ) {
174					return state;
175				}
176	
177				maxDate = moment( streamItems[ 0 ].date );
178	
179				if ( state.lastUpdated && maxDate.isSameOrBefore( state.lastUpdated ) ) {
180					return state;
181				}
182	
183				return { ...state, lastUpdated: maxDate };
184			case READER_STREAMS_UPDATES_RECEIVE:
185				streamItems = action.payload.streamItems;
186				if ( streamItems.length === 0 ) {
187					return state;
188				}
189	
190				maxDate = moment( streamItems[ 0 ].date );
191				minDate = moment( streamItems[ streamItems.length - 1 ].date );
192	
193				// only retain posts that are newer than ones we already have
194				if ( state.lastUpdated ) {
195					streamItems = streamItems.filter( ( item ) =>
196						moment( item.date ).isAfter( state.lastUpdated )
197					);
198				}
199	
200				if ( streamItems.length === 0 ) {
201					return state;
202				}
203	
204				newItems = [ ...streamItems ];
205	
206				// Find any x-posts and filter out duplicates
207				newXPosts = newItems.filter( ( postKey ) => postKey.xPostMetadata );
208	
209				if ( newXPosts ) {
210					newItems = combineXPosts( newItems );
211				}
212	
213				// there is a gap if the oldest item in the poll is newer than last update time
214				if ( state.lastUpdated && minDate.isAfter( state.lastUpdated ) ) {
215					newItems.push( {
216						isGap: true,
217						from: state.lastUpdated,
218						to: minDate,
219					} );
220				}
221	
222				return { lastUpdated: maxDate, items: newItems };
223			case READER_STREAMS_SHOW_UPDATES:
224				return { ...state, items: [] };
225			case READER_STREAMS_CLEAR:
226				return PENDING_ITEMS_DEFAULT;
227		}
228		return state;
229	};
230	
231	/*
232	 * Contains which postKey is currently selected.
233	 * This is relevant for keyboard navigation
234	 */
235	export const selected = ( state = null, action ) => {
236		switch ( action.type ) {
237			case READER_STREAMS_SELECT_ITEM: {
238				return action.payload.postKey;
239			}
240			case READER_STREAMS_SELECT_NEXT_ITEM: {
241				const idx = action.payload.items?.findIndex( ( item ) => keysAreEqual( item, state ) ) ?? -1;
242				return idx === action.payload.items.length - 1 ? state : action.payload.items[ idx + 1 ];
243			}
244			case READER_STREAMS_SELECT_PREV_ITEM: {
245				const idx = action.payload.items?.findIndex( ( item ) => keysAreEqual( item, state ) ) ?? -1;
246				return idx === 0 ? state : action.payload.items[ idx - 1 ];
247			}
248		}
249		return state;
250	};
251	
252	/*
253	 * Contains whether or not a request for a new page is in flight.
254	 * Most parts of Calypso don't need this data, but streams still do since we can't infer the status
255	 * from current state. Its possible to have a list of post-keys as the state, and yet be fetching another page.
256	 *
257	 * isRequesting data is mostly used for whether or not to render placeholders
258	 */
259	export const isRequesting = ( state = false, action ) => {
260		// this has become a lie! its not really whether we are requesting, just if we need to show
261		// placeholders at the bottom of the stream
262		switch ( action.type ) {
263			case READER_STREAMS_PAGE_REQUEST:
264			case READER_STREAMS_PAGINATED_REQUEST:
265				return state || ( ! action.payload.isPoll && ! action.payload.isGap );
266			case READER_STREAMS_PAGE_RECEIVE:
267				return false;
268		}
269		return state;
270	};
271	
272	/*
273	 * Contains whether or not a stream is at its end.
274	 * This data is used to tell our infinite-list components
275	 * to render its 'end-of-stream' and stop making requests for more data.
276	 */
277	export const lastPage = ( state = false, action ) => {
278		if ( action.type === READER_STREAMS_PAGE_RECEIVE ) {
279			return action.payload.streamItems.length === 0 || ! action.payload.pageHandle;
280		}
281		return state;
282	};
283	
284	/*
285	 * Contains the query params needed to be able to fetch the next page.
286	 * This usually gets handed to the request for more stream items
287	 */
288	export const pageHandle = ( state = null, action ) => {
289		if (
290			action.type === READER_STREAMS_PAGE_RECEIVE &&
291			! action.payload.isPoll &&
292			! action.payload.gap
293		) {
294			// Explicitly set pageHandle to null if server returns null.
295			return action.payload.pageHandle ?? null;
296		}
297		return state;
298	};
299	
300	export const pagination = ( state = { totalItems: 0, totalPages: 0 }, action ) => {
301		switch ( action.type ) {
302			case READER_STREAMS_PAGE_RECEIVE:
303				return {
304					totalItems: action.payload.totalItems,
305					totalPages: action.payload.totalPages,
306				};
307			case READER_STREAMS_CLEAR:
308				return { totalItems: 0, totalPages: 0 };
309			default:
310				return state;
311		}
312	};
313	
314	const streamReducer = combineReducers( {
315		items,
316		pendingItems,
317		selected,
318		lastPage,
319		isRequesting,
320		pageHandle,
321		pagination,
322	} );
323	
324	export default keyedReducer( 'payload.streamKey', streamReducer );
