4	import fs from 'fs';
5	import config from '@automattic/calypso-config';
6	import boot from './boot';
7	import { getLogger } from './lib/logger';
8	const logger = getLogger();
9	const start = Date.now();
10	
11	let protocol = config( 'protocol' );
12	let port = config( 'port' );
13	let host = config( 'hostname' );
14	
15	// Mock WordPress.com locally for auth development.
16	if ( process.env.MOCK_WORDPRESSDOTCOM === '1' ) {
17		protocol = 'https';
18		port = 443;
19		host = 'wordpress.com';
20		logger.warn( 'Ignoring protocol, port, and hostname configs to mock WordPress.com' );
21	}
22	
23	const app = boot();
24	
25	function sendBootStatus( status ) {
26		// don't send anything if we're not running in a fork
27		if ( ! process.send ) {
28			return;
29		}
30		process.send( { boot: status } );
31	}
32	
33	logger.info( 'wp-calypso booted in %dms - %s://%s:%s', Date.now() - start, protocol, host, port );
34	
35	function loadSslCert() {
36		const { execSync } = require( 'child_process' );
37		const execOptions = { encoding: 'utf-8', windowsHide: true };
38		let key = './config/server/key.pem';
39		let certificate = './config/server/certificate.pem';
40	
41		if ( ! fs.existsSync( key ) || ! fs.existsSync( certificate ) ) {
42			try {
43				execSync( 'openssl version', execOptions );
44				execSync(
45					`openssl req -x509 -newkey rsa:2048 -keyout ./config/server/key.tmp.pem -out ${ certificate } -days 365 -nodes -subj "/C=US/ST=Foo/L=Bar/O=Baz/CN=calypso.localhost"`,
46					execOptions
47				);
48				execSync( `openssl rsa -in ./config/server/key.tmp.pem -out ${ key }`, execOptions );
49				execSync( 'rm ./config/server/key.tmp.pem', execOptions );
50			} catch ( error ) {
51				key = './config/server/key.default.pem';
52				certificate = './config/server/certificate.default.pem';
53	
54				console.error( error );
55			}
56		}
57	
58		return {
59			key: fs.readFileSync( key ),
60			cert: fs.readFileSync( certificate ),
61		};
62	}
63	
64	// Start a development HTTPS server.
65	function createServer() {
66		if ( protocol === 'https' ) {
67			return require( 'https' ).createServer( loadSslCert(), app );
68		}
69	
70		return require( 'http' ).createServer( app );
71	}
72	
73	const server = createServer();
74	if ( process.env.NODE_ENV !== 'development' ) {
75		server.timeout = 50 * 1000; //50 seconds, in ms;
76	}
77	
78	process.on( 'uncaughtExceptionMonitor', ( err ) => {
79		logger.error( err );
80	} );
81	
82	// The desktop app runs Calypso in a fork. Let non-forks listen on any host.
83	server.listen( { port, host: process.env.CALYPSO_IS_FORK ? host : null }, function () {
84		// Tell the parent process that Calypso has booted.
85		sendBootStatus( 'ready' );
86	} );
