1	import { recordTracksEvent } from '@automattic/calypso-analytics';
2	import { Spinner } from '@automattic/components';
3	import { Icon, chevronLeft, chevronRight } from '@wordpress/icons';
4	import { useRtl, useTranslate } from 'i18n-calypso';
5	import { useCallback, useEffect, useRef, useState } from 'react';
6	import { useSelector } from 'react-redux';
7	import useSiteMenuItems from 'calypso/my-sites/sidebar/use-site-menu-items';
8	import { getIsRequestingAdminMenu } from 'calypso/state/admin-menu/selectors';
9	import getPreviousRoute from 'calypso/state/selectors/get-previous-route';
10	import { getSection } from 'calypso/state/ui/selectors';
11	import Sidebar from '../sidebar';
12	import { GLOBAL_SIDEBAR_EVENTS } from './events';
13	import './style.scss';
14	
15	const GlobalSidebar = ( {
16		children,
17		onClick = undefined,
18		className = '',
19		path = '',
20		...props
21	} ) => {
22		const wrapperRef = useRef( null );
23		const bodyRef = useRef( null );
24		const menuItems = useSiteMenuItems();
25		const isRequestingMenu = useSelector( getIsRequestingAdminMenu );
26		const translate = useTranslate();
27		const isRtl = useRtl();
28		const previousRoute = useSelector( getPreviousRoute );
29		const section = useSelector( getSection );
30		const [ previousLink, setPreviousLink ] = useState( '' );
31		const handleWheel = useCallback( ( event ) => {
32			const bodyEl = bodyRef.current;
33			if ( bodyEl && bodyEl.contains( event.target ) && bodyEl.scrollHeight > bodyEl.clientHeight ) {
34				event.preventDefault();
35				bodyEl.scrollTop += event.deltaY;
36			}
37		}, [] );
38	
39		const handleBackLinkClick = ( ev ) => {
40			recordTracksEvent( GLOBAL_SIDEBAR_EVENTS.MENU_BACK_CLICK, { path } );
41			if ( props.onClose ) {
42				ev.preventDefault();
43				ev.stopPropagation();
44				props.onClose();
45			}
46		};
47	
48		const getBackLinkFromURL = () => {
49			const searchParams = new URLSearchParams( window.location.search );
50			const url = searchParams.get( 'from' ) || '';
51	
52			// Only accept internal links for security purposes.
53			return url.startsWith( '/' ) ? url : '';
54		};
55	
56		useEffect( () => {
57			wrapperRef.current?.addEventListener( 'wheel', handleWheel, { passive: false } );
58			return () => {
59				wrapperRef.current?.removeEventListener( 'wheel', handleWheel );
60			};
61		}, [ handleWheel ] );
62	
63		useEffect( () => {
64			// Update the previous link only when the group is changed.
65			if ( previousRoute && ! previousRoute.startsWith( `/${ section.group }` ) ) {
66				setPreviousLink( previousRoute );
67			}
68		}, [ previousRoute, section.group ] );
69	
70		/**
71		 * If there are no menu items and we are currently requesting some,
72		 * then show a spinner. The check for menuItems is necessary because
73		 * we may choose to render the menu from statically stored JSON data
74		 * and therefore we need to be ready to render.
75		 */
76		if ( ! menuItems && isRequestingMenu ) {
77			return <Spinner className="sidebar__menu-loading" />;
78		}
79	
80		const { requireBackLink, siteTitle, backLinkHref, subHeading, ...sidebarProps } = props;
81		const sidebarBackLinkHref = getBackLinkFromURL() || backLinkHref || previousLink || '/sites';
82	
83		return (
84			<div className="global-sidebar" ref={ wrapperRef }>
85				<div className="sidebar__body" ref={ bodyRef }>
86					<Sidebar className={ className } { ...sidebarProps } onClick={ onClick }>
87						{ requireBackLink && (
88							<div className="sidebar__back-link">
89								<a href={ sidebarBackLinkHref } onClick={ handleBackLinkClick }>
90									<Icon icon={ isRtl ? chevronRight : chevronLeft } size={ 24 } />
91								</a>
92								<span className="sidebar__site-title">{ siteTitle || translate( 'Back' ) }</span>
93							</div>
94						) }
95						{ subHeading && <div className="sidebar__sub-heading">{ subHeading }</div> }
96						{ children }
97					</Sidebar>
98				</div>
99			</div>
100		);
101	};
102	
