29	export function syncReaderFollows( store ) {
30		if ( isSyncingFollows() ) {
31			return;
32		}
33	
34		syncingFollows = true;
35		seenSubscriptions = new Set();
36	
37		store.dispatch( syncReaderFollowsPage( 1 ) );
38	}
