40	export function requestPage( action ) {
41		const { page, number, meta } = action.payload;
42	
43		return http(
44			{
45				method: 'GET',
46				path: '/read/following/mine',
47				apiVersion: '1.2',
48				query: { page, number, meta },
49			},
50			action
51		);
52	}
53	
54	const MAX_PAGES_TO_FETCH = MAX_ITEMS / ITEMS_PER_PAGE;
55	
56	export const receivePage = ( action, apiResponse ) => ( dispatch ) => {
57		if ( ! isValidApiResponse( apiResponse ) ) {
58			dispatch( receiveError() );
59			return;
60		}
61	
62		const { page, number } = apiResponse;
63		const follows = subscriptionsFromApi( apiResponse );
64		let totalCount = null;
65	
66		// Only trust the total count if we're on the first page of results,
67		// or on subsequent pages where we have more than one follow returned
68		if ( page === 1 || number > 0 ) {
69			totalCount = apiResponse.total_subscriptions;
70		}
71	
72		dispatch( receiveFollows( { follows, totalCount } ) );
73	
74		forEach( follows, ( follow ) => seenSubscriptions.add( follow.feed_URL ) );
75	
76		// Fetch the next page of subscriptions where applicable
77		if ( number > 0 && page <= MAX_PAGES_TO_FETCH && isSyncingFollows() ) {
78			dispatch( syncReaderFollowsPage( page + 1 ) );
79			return;
80		}
81	
82		// all done syncing
83		dispatch( syncComplete( Array.from( seenSubscriptions ) ) );
84	
85		seenSubscriptions = null;
86		syncingFollows = false;
87	};
