107	export async function supportNextBoot() {
108		bypassPersistentStorage( true );
109	
110		// The following keys will not be bypassed as
111		// they are safe to share across user sessions.
112		const allowedKeys = [ 'debug' ];
113		localStorageBypass( { allowedKeys } );
114	
115		// This needs to be a dynamic import in order to avoid boot race conditions.
116		const { supportSessionActivate } = await asyncRequire( 'calypso/state/support/actions' );
117	
118		// the boot is performed before the Redux store is created, so we need to wait for a promise
119		const reduxStore = await reduxStoreReady;
120		reduxStore.dispatch( supportSessionActivate() );
