1	declare const process: {
2		env: {
3			NODE_ENV: unknown;
4		};
5	};
6	
7	interface GenerateCacheKey< A extends unknown[] > {
8		( ...args: A ): string;
9	}
10	
11	const defaultGetCacheKey: GenerateCacheKey< unknown[] > = ( ...args: unknown[] ): string =>
12		args.join();
13	
14	const isFunction = ( fn: unknown ): fn is ( ...args: unknown[] ) => unknown => {
15		return !! fn && typeof fn === 'function';
16	};
17	
18	const isObject = ( o: unknown ): o is Record< string, unknown > => {
19		return !! o && typeof o === 'object';
20	};
21	
22	type WeakMapKey = object; // eslint-disable-line @typescript-eslint/ban-types
23	
24	interface Options< A extends unknown[] > {
25		/** Custom way to compute the cache key from the `args` list */
26		getCacheKey?: GenerateCacheKey< A >;
27	}
28	
29	export interface CachedSelector< S, A extends unknown[], R = unknown > {
30		( state: S, ...args: A ): R;
31		clearCache: () => void;
32	}
33	
34	/**
35	 * Returns a selector that caches values.
36	 * @param getDependents A Function describing the dependent(s) of the selector.
37	 *                      Must return an array which gets passed as the first arg to the selector.
38	 * @param selector      A standard selector for calculating cached result.
39	 * @param options       Options bag with additional arguments.
40	 * @returns Cached selector
41	 */
42	export default function treeSelect<
43		State = unknown,
44		Args extends unknown[] = unknown[],
45		// Note: SArgs is only necessary because TS will attempt to infer Args
46		// from selector instead of getDependents, which causes issues when selector
47		// doesn't utilize args.
48		// Same issue as https://github.com/Automattic/wp-calypso/pull/74540#issuecomment-1650834391
49		SArgs extends Args = Args,
50		Deps extends WeakMapKey[] = any[], // eslint-disable-line @typescript-eslint/no-explicit-any
51		Result = unknown,
52	>(
53		getDependents: ( state: State, ...args: Args ) => Deps,
54		selector: ( deps: Deps, ...args: SArgs ) => Result,
55		options: Options< Args > = {}
56	): CachedSelector< State, Args, Result > {
57		if ( process.env.NODE_ENV !== 'production' ) {
58			if ( ! isFunction( getDependents ) || ! isFunction( selector ) ) {
59				throw new TypeError(
60					'treeSelect: invalid arguments passed, selector and getDependents must both be functions'
61				);
62			}
63		}
64	
65		let cache = new WeakMap();
66	
67		const { getCacheKey = defaultGetCacheKey } = options;
68	
69		const cachedSelector: CachedSelector< State, Args, Result > = function (
70			state: State,
71			...args: Args
72		) {
73			const dependents = getDependents( state, ...args );
74	
75			if ( process.env.NODE_ENV !== 'production' ) {
76				if ( getCacheKey === defaultGetCacheKey && args.some( isObject ) ) {
77					throw new Error( 'Do not pass objects as arguments to a treeSelector' );
78				}
79			}
80	
81			// create a dependency tree for caching selector results.
82			// this is beneficial over standard memoization techniques so that we can
83			// garbage collect any values that are based on outdated dependents
84			const leafCache: Map< string, Result > = dependents.reduce( insertDependentKey, cache );
85	
86			const key = getCacheKey( ...args );
87			if ( leafCache.has( key ) ) {
88				return leafCache.get( key ) as Result;
89			}
90	
91			const value = selector( dependents, ...( args as SArgs ) );
92			leafCache.set( key, value );
93			return value;
94		};
95	
96		cachedSelector.clearCache = () => {
97			// WeakMap doesn't have `clear` method, so we need to recreate it
98			cache = new WeakMap();
99		};
100	
101		return cachedSelector;
102	}
103	
104	/*
105	 * This object will be used as a WeakMap key if a dependency is a falsy value (null, undefined, ...)
106	 */
107	const NULLISH_KEY = {};
108	
109	/*
110	 * First tries to get the value for the key.
111	 * If the key is not present, then inserts a new map and returns it
112	 *
113	 * Note: Inserts WeakMaps except for the last map which will be a regular Map.
114	 * The last map is a regular one because the the key for the last map is the string results of args.join().
115	 */
116	function insertDependentKey( map: any, key: unknown, currentIndex: number, arr: unknown[] ) {
117		// eslint-disable-line @typescript-eslint/no-explicit-any
118		if ( key != null && Object( key ) !== key ) {
119			throw new TypeError( 'key must be an object, `null`, or `undefined`' );
120		}
121		const weakMapKey = key || NULLISH_KEY;
122	
123		const existingMap = map.get( weakMapKey );
124		if ( existingMap ) {
125			return existingMap;
126		}
127	
128		const newMap = currentIndex === arr.length - 1 ? new Map() : new WeakMap();
129		map.set( weakMapKey, newMap );
130		return newMap;
131	}
