1	/**
2	 * Returns true if the two arrays are shallow equal, or false otherwise.
3	 *
4	 * @param {any[]} a First array to compare.
5	 * @param {any[]} b Second array to compare.
6	 *
7	 * @return {boolean} Whether the two arrays are shallow equal.
8	 */
9	export default function isShallowEqualArrays( a, b ) {
10		if ( a === b ) {
11			return true;
12		}
13	
14		if ( a.length !== b.length ) {
15			return false;
16		}
17	
18		for ( let i = 0, len = a.length; i < len; i++ ) {
19			if ( a[ i ] !== b[ i ] ) {
20				return false;
21			}
22		}
23	
24		return true;
25	}
