1	/**
2	 * Returns true if the two objects are shallow equal, or false otherwise.
3	 *
4	 * @param {import('.').ComparableObject} a First object to compare.
5	 * @param {import('.').ComparableObject} b Second object to compare.
6	 *
7	 * @return {boolean} Whether the two objects are shallow equal.
8	 */
9	export default function isShallowEqualObjects( a, b ) {
10		if ( a === b ) {
11			return true;
12		}
13	
14		const aKeys = Object.keys( a );
15		const bKeys = Object.keys( b );
16	
17		if ( aKeys.length !== bKeys.length ) {
18			return false;
19		}
20	
21		let i = 0;
22	
23		while ( i < aKeys.length ) {
24			const key = aKeys[ i ];
25			const aValue = a[ key ];
26	
27			if (
28				// In iterating only the keys of the first object after verifying
29				// equal lengths, account for the case that an explicit `undefined`
30				// value in the first is implicitly undefined in the second.
31				//
32				// Example: isShallowEqualObjects( { a: undefined }, { b: 5 } )
33				( aValue === undefined && ! b.hasOwnProperty( key ) ) ||
34				aValue !== b[ key ]
35			) {
36				return false;
37			}
38	
39			i++;
40		}
41	
42		return true;
43	}
