9	/**
10	 * Defines acceptable argument types for a memoized selector when using the
11	 * default cache key generating function.
12	 */
13	const VALID_ARG_TYPES = [ 'number', 'boolean', 'string' ] as string[];
14	
15	type Dependant< TState, TProps extends any[], TDependency > = (
16		state: TState,
17		...props: TProps
18	) => TDependency;
19	
20	/**
21	 * Default behavior for determining whether current state differs from previous
22	 * state, which is the basis upon which memoize cache is cleared. Should return
23	 * a value or array of values to be shallowly compared for strict equality.
24	 * @param state Current state object
25	 * @returns Value(s) to be shallow compared
26	 */
27	const DEFAULT_GET_DEPENDANTS: Dependant< any, any, any > = < TState >( state: TState ): TState =>
28		state;
29	
30	/**
31	 * At runtime, assigns a function which returns a cache key for the memoized
32	 * selector function, given a state object and a variable set of arguments. In
33	 * development mode, this warns when the memoized selector is passed a complex
34	 * object argument, as these cannot be depended upon as reliable cache keys.
35	 */
36	const DEFAULT_GET_CACHE_KEY = ( () => {
37		if ( 'production' === process.env.NODE_ENV ) {
38			return ( _: unknown, ...args: unknown[] ) => args.join();
39		}
40	
41		return ( _: unknown, ...args: unknown[] ) => {
42			const hasInvalidArg = args.some( ( arg ) => {
43				return arg && ! VALID_ARG_TYPES.includes( typeof arg );
44			} );
45	
46			if ( hasInvalidArg ) {
47				warn( 'Do not pass complex objects as arguments for a memoized selector' );
48			}
49	
50			return args.join();
51		};
52	} )();
