54	/**
55	 * Given an array of getDependants functions, returns a single function which,
56	 * when called, returns an array of mapped results from those functions.
57	 * @param dependants Array of getDependants
58	 * @returns Function mapping getDependants results
59	 */
60	const makeSelectorFromArray =
61		< TState, TProps extends any[] >( dependants: ( ( state: TState, ...args: TProps ) => any )[] ) =>
62		( state: TState, ...args: TProps ) =>
63			dependants.map( ( dependant ) => dependant( state, ...args ) );
64	
65	/**
66	 * Returns a memoized state selector for use with the global application state.
67	 * @param selector      Function calculating cached result
68	 * @param getDependants Function(s) describing dependent
69	 *                                             state, or an array of dependent
70	 *                                             state selectors
71	 * @param getCacheKey   Function generating cache key
72	 * @returns Memoized selector
73	 */
74	export default function createSelector<
75		TState,
76		TProps extends any[],
77		// Note: TDepProps is only necessary because TS will attempt to infer TProps
78		// from getDependants instead of selector, which causes issues when getDependants
79		// only uses state, not props.
80		// See https://github.com/Automattic/wp-calypso/pull/74540#issuecomment-1650834391
81		TDepProps extends TProps,
82		TDerivedState,
83	>(
84		selector: ( state: TState, ...props: TProps ) => TDerivedState,
85		getDependants:
86			| Dependant< TState, TDepProps, any >
87			| Dependant< TState, TDepProps, any >[] = DEFAULT_GET_DEPENDANTS,
88		getCacheKey: ( state: TState, ...props: TProps ) => string = DEFAULT_GET_CACHE_KEY
89	): ( state: TState, ...props: TProps ) => TDerivedState {
90		const memoizedSelector = memoize( selector, getCacheKey );
91		let lastDependants: any[];
92	
93		const getDependantsFn =
94			typeof getDependants === 'function' ? getDependants : makeSelectorFromArray( getDependants );
95	
96		return Object.assign(
97			function ( state: TState, ...args: TProps ) {
98				let currentDependants = getDependantsFn( state, ...( args as TDepProps ) );
99				if ( ! Array.isArray( currentDependants ) ) {
100					currentDependants = [ currentDependants ];
101				}
102	
103				if ( lastDependants && ! isShallowEqual( currentDependants, lastDependants ) ) {
104					memoizedSelector.cache.clear?.();
105				}
106	
107				lastDependants = currentDependants;
108	
109				return memoizedSelector( state, ...args );
110			},
111			{ memoizedSelector }
112		);
113	}
