2	 * Internal dependencies
3	 */
4	import isShallowEqualObjects from './objects';
5	import isShallowEqualArrays from './arrays';
6	
7	export { default as isShallowEqualObjects } from './objects';
8	export { default as isShallowEqualArrays } from './arrays';
9	
10	/**
11	 * @typedef {Record<string, any>} ComparableObject
12	 */
13	
14	/**
15	 * Returns true if the two arrays or objects are shallow equal, or false
16	 * otherwise. Also handles primitive values, just in case.
17	 *
18	 * @param {unknown} a First object or array to compare.
19	 * @param {unknown} b Second object or array to compare.
20	 *
21	 * @return {boolean} Whether the two values are shallow equal.
22	 */
23	export default function isShallowEqual( a, b ) {
24		if ( a && b ) {
25			if ( a.constructor === Object && b.constructor === Object ) {
26				return isShallowEqualObjects( a, b );
27			} else if ( Array.isArray( a ) && Array.isArray( b ) ) {
28				return isShallowEqualArrays( a, b );
29			}
30		}
31	
32		return a === b;
33	}
