54	export class MissingExperimentAssignmentError extends Error {
55		constructor( message?: string ) {
56			super( message );
57	
58			// Maintains proper stack trace for where our error was thrown (only available on V8)
59			if ( Error.captureStackTrace ) {
60				Error.captureStackTrace( this, MissingExperimentAssignmentError );
61			}
62	
