67	/**
68	 * Create an ExPlat Client
69	 * @param config Configuration object
70	 */
71	export function createExPlatClient( config: Config ): ExPlatClient {
72		if ( typeof window === 'undefined' ) {
73			throw new Error( 'Running outside of a browser context.' );
74		}
75	
76		/**
77		 * This bit of code is the heavy lifting behind loadExperimentAssignment, allowing it to be used intuitively.
78		 *
79		 * Using asyncOneAtATime, is how we ensure for each experiment that there is only ever one fetch process occuring.
80		 * @param experimentName The experiment's name
81		 */
82		const createWrappedExperimentAssignmentFetchAndStore = ( experimentName: string ) =>
83			Timing.asyncOneAtATime( async () => {
84				const fetchedExperimentAssignment = await Request.fetchExperimentAssignment(
85					config,
86					experimentName
87				);
88				storeExperimentAssignment( fetchedExperimentAssignment );
89				return fetchedExperimentAssignment;
90			} );
91		const experimentNameToWrappedExperimentAssignmentFetchAndStore: Record<
92			string,
93			() => Promise< ExperimentAssignment >
94		> = {};
95	
96		const safeLogError: typeof config.logError = ( ...args ) => {
97			try {
98				config.logError( ...args );
99			} catch ( e ) {}
100		};
101	
102		// Clean up LocalStorage on start up
103		try {
104			removeExpiredExperimentAssignments();
105		} catch ( error ) {
106			safeLogError( {
107				message: ( error as Error ).message,
108				source: 'removeExpiredExperimentAssignments-error',
109			} );
110		}
111	
112		return {
113			loadExperimentAssignment: async ( experimentName: string ): Promise< ExperimentAssignment > => {
114				try {
115					if ( ! Validation.isName( experimentName ) ) {
116						throw new Error( `Invalid experimentName: "${ experimentName }"` );
117					}
118	
119					const storedExperimentAssignment = retrieveExperimentAssignment( experimentName );
120					if (
121						storedExperimentAssignment &&
122						ExperimentAssignments.isAlive( storedExperimentAssignment )
123					) {
124						return storedExperimentAssignment;
125					}
126	
127					if (
128						experimentNameToWrappedExperimentAssignmentFetchAndStore[ experimentName ] === undefined
129					) {
130						experimentNameToWrappedExperimentAssignmentFetchAndStore[ experimentName ] =
131							createWrappedExperimentAssignmentFetchAndStore( experimentName );
132					}
133	
134					// Temporarilly running an A/B experiment on the timeout, see https://github.com/Automattic/wp-calypso/pull/54507
135					let experimentFetchTimeout = EXPERIMENT_FETCH_TIMEOUT;
136					if ( Math.random() > 0.5 ) {
137						experimentFetchTimeout = 5000;
138					}
139	
140					// We time out the request here and not above so the fetch-and-store continues and can be
141					// returned by future uses of loadExperimentAssignment.
142					const fetchedExperimentAssignment = await Timing.timeoutPromise(
143						experimentNameToWrappedExperimentAssignmentFetchAndStore[ experimentName ](),
144						experimentFetchTimeout
145					);
146					if ( ! fetchedExperimentAssignment ) {
147						throw new Error( 'Could not fetch ExperimentAssignment' );
148					}
149	
150					return fetchedExperimentAssignment;
151				} catch ( initialError ) {
152					safeLogError( {
153						message: ( initialError as Error ).message,
154						experimentName,
155						source: 'loadExperimentAssignment-initialError',
156					} );
157				}
158	
159				// Fetching failed and we're not in development mode.
160				try {
161					// We provide stale ExperimentAssignments, important for offline users.
162					const storedExperimentAssignment = retrieveExperimentAssignment( experimentName );
163					if ( storedExperimentAssignment ) {
164						return storedExperimentAssignment;
165					}
166	
167					// We are syncronously trying to retrieve and then store a fallback which means this fallback will
168					// be retrieved by all other loadExperimentAssignments that are currently running or will run,
169					// preventing a run on the server.
170					const fallbackExperimentAssignment = createFallbackExperimentAssignment( experimentName );
171					storeExperimentAssignment( fallbackExperimentAssignment );
172					return fallbackExperimentAssignment;
173				} catch ( fallbackError ) {
174					safeLogError( {
175						message: ( fallbackError as Error ).message,
176						experimentName,
177						source: 'loadExperimentAssignment-fallbackError',
178					} );
179	
180					// As a last resort we just keep it very simple
181					return createFallbackExperimentAssignment( experimentName );
182				}
183			},
184			dangerouslyGetExperimentAssignment: ( experimentName: string ): ExperimentAssignment => {
185				try {
186					if ( ! Validation.isName( experimentName ) ) {
187						throw new Error( `Invalid experimentName: ${ experimentName }` );
188					}
189	
190					const storedExperimentAssignment = retrieveExperimentAssignment( experimentName );
191					if ( ! storedExperimentAssignment ) {
192						throw new Error(
193							"Trying to dangerously get an ExperimentAssignment that hasn't loaded."
194						);
195					}
196	
197					// We want to be loud in development mode to help pick up any issues:
198					if ( config.isDevelopmentMode ) {
199						// Highlight when we dangerously get an experiment too soon to when we load one:
200						if (
201							storedExperimentAssignment &&
202							Timing.monotonicNow() - storedExperimentAssignment.retrievedTimestamp < 1000
203						) {
204							safeLogError( {
205								message:
206									'Warning: Trying to dangerously get an ExperimentAssignment too soon after loading it.',
207								experimentName,
208								source: 'dangerouslyGetExperimentAssignment',
209							} );
210						}
211					}
212	
213					return storedExperimentAssignment;
214				} catch ( error ) {
