2	import * as React from 'react';
3	import type { ExPlatClient, ExperimentAssignment } from '@automattic/explat-client';
4	
5	export interface ExperimentOptions {
6		/**
7		 * Determines whether a participant is currenlty eligible for an assignment.
8		 * - Only loads the experimentAssignment if isEligible is true.
9		 * - Only returns the experimentAssignment if isEligible is true.
10		 */
11		isEligible?: boolean;
12	}
13	
14	const defaultExperimentOptions = {
15		isEligible: true,
16	};
17	
18	export interface ExPlatClientReactHelpers {
19		/**
20		 * An ExPlat useExperiment hook.
21		 *
22		 * NOTE: Doesn't obey ExperimentAssignment TTL in order to keep stable UX.
23		 * @returns [isExperimentAssignmentLoading, ExperimentAssignment | null]
24		 */
25		useExperiment: (
26			experimentName: string,
27			options?: ExperimentOptions
28		) => [ boolean, ExperimentAssignment | null ];
29	
30		/**
31		 * Experiment component, safest and simplest, should be first choice if usable.
32		 */
33		Experiment: ( props: {
34			name: string;
35			defaultExperience: React.ReactNode;
36			treatmentExperience: React.ReactNode;
37			loadingExperience: React.ReactNode;
38			options?: ExperimentOptions;
39		} ) => JSX.Element;
40	
41		/**
42		 * Inject experiment data into a child component.
43		 * Use when hooks aren't available.
44		 */
45		ProvideExperimentData: ( props: {
46			children: (
47				isLoading: boolean,
48				experimentAssignment: ExperimentAssignment | null
49			) => JSX.Element;
50			name: string;
51			options?: ExperimentOptions;
52		} ) => JSX.Element;
53	}
54	
55	export default function createExPlatClientReactHelpers(
56		exPlatClient: ExPlatClient
57	): ExPlatClientReactHelpers {
58		const useExperiment = (
59			experimentName: string,
60			providedOptions: ExperimentOptions = {}
61		): [ boolean, ExperimentAssignment | null ] => {
62			const options: Required< ExperimentOptions > = {
63				...defaultExperimentOptions,
64				...providedOptions,
65			};
66	
67			// Manual updates to ensure rerendering when we want it:
68			// https://legacy.reactjs.org/docs/hooks-faq.html#is-there-something-like-forceupdate
69			const [ , forceUpdate ] = useReducer( ( x ) => x + 1, 0 );
70			const previousExperimentNameRef = useRef( experimentName );
71	
72			useEffect( () => {
73				let isSubscribed = true;
74				if ( options.isEligible ) {
75					exPlatClient.loadExperimentAssignment( experimentName ).then( () => {
76						if ( isSubscribed ) {
77							forceUpdate();
78						}
79					} );
80				}
81				return () => {
82					isSubscribed = false;
83				};
84			}, [ experimentName, options.isEligible ] );
85	
86			if (
87				experimentName !== previousExperimentNameRef.current &&
88				! previousExperimentNameRef.current.startsWith( 'explat_test' )
89			) {
90				exPlatClient.config.logError( {
91					message: '[ExPlat] useExperiment: experimentName should never change between renders!',
92				} );
93			}
94	
95			if ( ! options.isEligible ) {
96				return [ false, null ];
97			}
98	
99			const maybeExperimentAssignment =
100				exPlatClient.dangerouslyGetMaybeLoadedExperimentAssignment( experimentName );
101			return [ ! maybeExperimentAssignment, maybeExperimentAssignment ];
102		};
103	
104		const Experiment = ( {
105			defaultExperience,
106			treatmentExperience,
107			loadingExperience,
108			name: experimentName,
109			options,
110		}: {
111			defaultExperience: React.ReactNode;
112			treatmentExperience: React.ReactNode;
113			loadingExperience: React.ReactNode;
114			name: string;
115			options?: ExperimentOptions;
116		} ) => {
117			const [ isLoading, experimentAssignment ] = useExperiment( experimentName, options );
118			if ( isLoading ) {
119				return <>{ loadingExperience }</>;
120			} else if ( ! experimentAssignment?.variationName ) {
121				return <>{ defaultExperience }</>;
122			}
123			return <>{ treatmentExperience }</>;
124		};
125	
126		const ProvideExperimentData = ( {
127			children,
128			name: experimentName,
129			options,
130		}: {
131			children: (
132				isLoading: boolean,
133				experimentAssignment: ExperimentAssignment | null
134			) => JSX.Element;
135			name: string;
136			options?: ExperimentOptions;
137		} ) => {
138			const [ isLoading, experimentAssignment ] = useExperiment( experimentName, options );
139			return children( isLoading, experimentAssignment );
140		};
141	
142		return {
143			useExperiment,
144			Experiment,
145			ProvideExperimentData,
146		};
147	}
