15	 */
16	export function isFetchExperimentAssignmentResponse(
17		response: unknown
18	): response is FetchExperimentAssignmentResponse {
19		return (
20			isObject( response ) &&
21			isObject( response.variations ) &&
22			typeof response.ttl === 'number' &&
23			0 < response.ttl
24		);
25	}
