27	function validateFetchExperimentAssignmentResponse(
28		response: unknown
29	): FetchExperimentAssignmentResponse {
30		if ( isFetchExperimentAssignmentResponse( response ) ) {
31			return response;
32		}
33		throw new Error( 'Invalid FetchExperimentAssignmentResponse' );
