36	// We cache the anonId and add it to requests to ensure users that have recently
37	// crossed the logged-out/logged-in boundry have a consistent assignment.
38	//
39	// There can be issues otherwise as matching anonId to userId is only eventually
40	// consistent.
41	const localStorageLastAnonIdKey = 'explat-last-anon-id';
42	const localStorageLastAnonIdRetrievalTimeKey = 'explat-last-anon-id-retrieval-time';
43	const lastAnonIdExpiryTimeMs = 24 * 60 * 60 * 1000; // 24 hours
44	/**
45	 * INTERNAL USE ONLY
46	 *
47	 * Runs the getAnonId provided cached by LocalStorage:
48	 * - Returns the result of getAnonId if it can
49	 * - Otherwise, within the expiry time, returns the cached anonId
50	 *
51	 * Exported for testing.
52	 * @param getAnonId The getAnonId function
53	 */
54	export const localStorageCachedGetAnonId = async ( getAnonId: Config[ 'getAnonId' ] ) => {
55		const anonId = await getAnonId();
56		if ( anonId ) {
57			localStorage.setItem( localStorageLastAnonIdKey, anonId );
58			localStorage.setItem( localStorageLastAnonIdRetrievalTimeKey, String( monotonicNow() ) );
59			return anonId;
60		}
61	
62		const maybeStoredAnonId = localStorage.getItem( localStorageLastAnonIdKey );
63		const maybeStoredRetrievalTime = localStorage.getItem( localStorageLastAnonIdRetrievalTimeKey );
64		if (
65			maybeStoredAnonId &&
66			maybeStoredRetrievalTime &&
67			monotonicNow() - parseInt( maybeStoredRetrievalTime, 10 ) < lastAnonIdExpiryTimeMs
68		) {
69			return maybeStoredAnonId;
70		}
71	
72		return null;
73	};
