75	/**
76	 * Fetch an ExperimentAssignment
77	 * @param config The config object providing dependecy injection.
78	 * @param experimentName The experiment name to fetch
79	 */
80	export async function fetchExperimentAssignment(
81		config: Config,
82		experimentName: string
83	): Promise< ExperimentAssignment > {
84		const retrievedTimestamp = monotonicNow();
85	
86		const { variations, ttl: responseTtl } = validateFetchExperimentAssignmentResponse(
87			await config.fetchExperimentAssignment( {
88				anonId: await localStorageCachedGetAnonId( config.getAnonId ),
89				experimentName,
90			} )
91		);
92	
93		const ttl = Math.max( ExperimentAssignments.minimumTtl, responseTtl );
94	
95		const fetchedExperimentAssignments = Object.entries( variations )
96			.map( ( [ experimentName, variationName ] ) => ( {
97				experimentName,
98				variationName,
99				retrievedTimestamp,
100				ttl,
101			} ) )
102			.map( validateExperimentAssignment );
103	
104		if ( fetchedExperimentAssignments.length > 1 ) {
105			throw new Error(
106				'Received multiple experiment assignments while trying to fetch exactly one.'
107			);
108		}
109	
110		if ( fetchedExperimentAssignments.length === 0 ) {
111			return ExperimentAssignments.createFallbackExperimentAssignment( experimentName, ttl );
112		}
113	
114		const fetchedExperimentAssignment = fetchedExperimentAssignments[ 0 ];
115	
116		if ( fetchedExperimentAssignment.experimentName !== experimentName ) {
117			throw new Error(
118				"Newly fetched ExperimentAssignment's experiment name does not match request."
119			);
120		}
121	
122		if ( ! ExperimentAssignments.isAlive( fetchedExperimentAssignment ) ) {
123			throw new Error( "Newly fetched experiment isn't alive." );
124		}
125	
126		return fetchedExperimentAssignment;
127	}
