1	import {
2		getCurrentUser,
3		recordTracksEvent,
4		getTracksAnonymousUserId,
5		getTracksLoadPromise,
6	} from '@automattic/calypso-analytics';
7	import { logError } from './log-error';
8	
9	// SSR safety: Fail TypeScript compilation if `window` is used without an explicit undefined check
10	declare const window: undefined | ( Window & typeof globalThis );
11	
12	/**
13	 * setInterval, but it runs first callback immediately instead of after interval.
14	 * @param f The callback function
15	 * @param intervalMs The interval in milliseconds
16	 */
17	const immediateStartSetInterval = ( f: () => void, intervalMs: number ) => {
18		f();
19		return setInterval( f, intervalMs );
20	};
21	
22	let initializeAnonIdPromise: null | Promise< string | null > = null;
23	const anonIdPollingIntervalMilliseconds = 50;
24	const anonIdPollingIntervalMaxAttempts = 100; // 50 * 100 = 5000 = 5 seconds
25	/**
26	 * Initializes the anonId:
27	 * - Polls for AnonId receival
28	 * - Should only be called once at startup
29	 * - Happens to be safe to call multiple times if it is necessary to reset the anonId - something like this was necessary for testing.
30	 *
31	 * This purely for boot-time initialization, in usual circumstances it will be retrieved within 100-300ms, it happens in parallel booting
32	 * so should only delay experiment loading that much for boot-time experiments. In some circumstances such as a very slow connection this
33	 * can take a lot longer.
34	 *
35	 * The state of initializeAnonIdPromise should be used rather than the return of this function.
36	 * The return is only avaliable to make this easier to test.
37	 *
38	 * Throws on error.
39	 */
40	export const initializeAnonId = async (): Promise< string | null > => {
41		if ( typeof window === 'undefined' ) {
42			logError( { message: 'Trying to initialize anonId outside of a browser context.' } );
43			return null;
44		}
45	
46		recordTracksEvent( 'calypso_explat_initialization' );
47	
48		let attempt = 0;
49		initializeAnonIdPromise = new Promise( ( res ) => {
50			let anonIdPollingInterval: NodeJS.Timeout;
51			// eslint-disable-next-line prefer-const
52			anonIdPollingInterval = immediateStartSetInterval( () => {
53				const anonId = getTracksAnonymousUserId();
54				if ( typeof anonId === 'string' && anonId !== '' ) {
55					clearInterval( anonIdPollingInterval );
56					res( anonId );
57					return;
58				}
59	
60				if ( anonIdPollingIntervalMaxAttempts - 1 <= attempt || getCurrentUser() ) {
61					clearInterval( anonIdPollingInterval );
62					res( null );
63					return;
64				}
65				attempt = attempt + 1;
66			}, anonIdPollingIntervalMilliseconds );
67	
68			// Tracks can fail to load, e.g. because of an ad-blocker
69			getTracksLoadPromise().catch( () => {
70				clearInterval( anonIdPollingInterval );
71				res( null );
72			} );
73		} );
74	
75		return initializeAnonIdPromise;
76	};
77	
78	/**
79	 * Returns a user's anonId if they have.
80	 *
81	 * Safe in SSR, never throws in production.
82	 */
83	export const getAnonId = async (): Promise< string | null > => {
84		if ( typeof window === 'undefined' ) {
85			logError( { message: 'Trying to getAnonId in non browser context.' } );
86			return null;
87		}
88	
89		if ( initializeAnonIdPromise === null ) {
90			logError( { message: 'AnonId initialization should have started before this function call.' } );
91		}
92	
93		try {
94			return await initializeAnonIdPromise;
95		} catch ( e ) {
96			// We log errors on initializeAnonIdPromise and not here to prevent duplicates
97			// and keep things simple. It is safe to return null in an error case as we
98			// log those on the server.
99		}
100	
101		return null;
102	};
