3	let lastNow = Date.now();
4	/**
5	 * Returns the time in miliseconds.
6	 * A strictly increasing version of Date.now()
7	 *
8	 * Gives us some minimimal guarentees about user clocks.
9	 */
10	export function monotonicNow(): number {
11		const maybeNow = Date.now();
12	
13		lastNow = lastNow < maybeNow ? maybeNow : lastNow + 1;
14	
15		return lastNow;
16	}
17	
18	/**
19	 * Timeouts a promise. Returns timeoutValue in event of timeout.
20	 * @param promise The promise to timeout
21	 * @param timeoutMilliseconds The timeout time in milliseconds
22	 */
23	export function timeoutPromise< T >(
24		promise: Promise< T >,
25		timeoutMilliseconds: number
26	): Promise< T | null > {
27		return Promise.race( [
28			promise,
29			new Promise< null >( ( _res, rej ) =>
30				setTimeout(
31					() => rej( new Error( `Promise has timed-out after ${ timeoutMilliseconds }ms.` ) ),
32					timeoutMilliseconds
33				)
34			),
35		] );
36	}
37	
38	/**
39	 * Wraps an async function so that if it is called multiple times it will just return the same promise - until the promise is fulfilled.
40	 *
41	 * Once the promise has been fulfilled it will reset.
42	 * @param f The function to wrap
43	 */
44	export function asyncOneAtATime< T >( f: () => Promise< T > ): () => Promise< T > {
45		let lastPromise: Promise< T > | null = null;
46		return () => {
47			if ( ! lastPromise ) {
48				lastPromise = f().finally( () => {
49					lastPromise = null;
50				} );
51			}
52			return lastPromise;
53		};
54	}
