17	/**
18	 * Store an ExperimentAssignment.
19	 * @param experimentAssignment The ExperimentAssignment
20	 */
21	export function storeExperimentAssignment( experimentAssignment: ExperimentAssignment ): void {
22		Validations.validateExperimentAssignment( experimentAssignment );
23	
24		const previousExperimentAssignment = retrieveExperimentAssignment(
25			experimentAssignment.experimentName
26		);
27		if (
28			previousExperimentAssignment &&
29			experimentAssignment.retrievedTimestamp < previousExperimentAssignment.retrievedTimestamp
30		) {
31			throw new Error(
32				'Trying to store an older experiment assignment than is present in the store, likely a race condition.'
33			);
34		}
35	
36		localStorage.setItem(
37			localStorageExperimentAssignmentKey( experimentAssignment.experimentName ),
38			JSON.stringify( experimentAssignment )
39		);
40	}
