42	/**
43	 * Retrieve an ExperimentAssignment.
44	 * @param experimentName The experiment name.
45	 */
46	export function retrieveExperimentAssignment(
47		experimentName: string
48	): ExperimentAssignment | undefined {
49		const maybeExperimentAssignmentJson = localStorage.getItem(
50			localStorageExperimentAssignmentKey( experimentName )
51		);
52		if ( ! maybeExperimentAssignmentJson ) {
53			return undefined;
54		}
55	
56		return Validations.validateExperimentAssignment( JSON.parse( maybeExperimentAssignmentJson ) );
