85	export function removeExpiredExperimentAssignments(): void {
86		getAllLocalStorageKeys()
87			.filter( isLocalStorageExperimentAssignmentKey )
88			.map( experimentNameFromLocalStorageExperimentAssignmentKey )
89			.filter( ( experimentName ) => {
