237				case 'run_describe_start': {
238					// If failure has been noted in a prior step/describe block, skip
239					// all subsequent describe blocks.
240					if ( this.failure ) {
241						event.describeBlock.mode = 'skip';
242					}
243					this.allure?.startSuite( event.describeBlock.name );
244					break;
245				}
246				case 'hook_start':
247					this.allure?.startHook( event.hook.type );
248					break;
249				case 'hook_success':
250					this.allure?.endHook();
251					break;
252				case 'hook_failure':
253					this.allure?.endHook( event.error ?? event.hook.asyncError );
254					this.failure = { type: 'hook', name: event.hook.type };
255					// Jest does not treat hook failures as actual failures, so output are
256					// suppressed. Manually display the error.
257					console.error(
258						`ERROR: ${ event.hook.parent.name } > ${ event.hook.type }\n\n`,
259						event.error,
260						'\n'
261					);
262					break;
263				case 'test_start':
264					// This event is fired not only for test steps but also the hooks.
265					// Precisely speaking, this event is fired after the `beforeAll` hooks
266					// but prior to the `beforeEach` as well.
267					// This means that stats for test results will be muddled if any `beforeEach`
268					// hooks are present.
269					// In addition, the following code snippet is replicated from `test_fn_start`
270					// due to https://github.com/Automattic/wp-calypso/pull/70154.
271					// Without this snippet, Jest will continue executing test steps within the
272					// nested `describe` block despite a failure in an earlier step.
273					if ( this.failure?.type === 'test' ) {
274						event.test.mode = 'skip';
275					}
276					break;
277				case 'test_fn_start':
278					// This event is fired after both the `beforeAll` and `beforeEach` hooks.
279					// Since this event fires after `beforeEach` hooks, it is the best way to detect
280					// an actual `it/test` step as having started.
281					// See https://github.com/facebook/jest/blob/main/packages/jest-types/src/Circus.ts#L132-L133
282					this.allure?.startTestStep( event.test, state, this.testFilename );
283					// If a test has failed, skip rest of the steps.
284					if ( this.failure?.type === 'test' ) {
285						event.test.mode = 'skip';
286					}
287					break;
288				case 'test_skip':
289					this.allure?.startTestStep( event.test, state, this.testFilename );
290					this.allure?.pendingTestStep( event.test );
291					break;
292				case 'test_fn_success': {
293					this.allure?.passTestStep();
294					break;
295				}
296				case 'test_fn_failure': {
297					this.failure = { type: 'test', name: event.test.name };
298					this.allure?.failTestStep( event.error );
299					break;
300				}
301				case 'test_done': {
302					// Event is fired when the test step is complete, including all pre- and
303					// after-hooks. Therefore we tell Allure that the test step has completely
304					// finished.
305					this.allure?.endTestStep();
306					break;
307				}
308				case 'run_describe_finish': {
309					break;
310				}
311				case 'teardown': {
312					// Teardown is completed in its own function that runs after the spec is
313					// complete.
314					break;
315				}
316				case 'run_finish':
317					// Wrap up the Allure report for the file.
318					this.allure?.endTestFile();
