380	 *
381	 * @see {@link  https://playwright.dev/docs/api/class-testoptions}
382	 * @returns {Browser} Proxy-trapped instance of a browser.
383	 */
384	function setupBrowserProxyTrap( browser: Browser ): Browser {
385		return new Proxy( browser, {
386			get: function ( target, prop: keyof Browser ) {
387				const orig = target[ prop ];
388	
389				if ( typeof orig !== 'function' ) {
390					return orig;
391				}
392	
393				if ( prop === 'newContext' ) {
394					return async function ( options: BrowserContextOptions ): Promise< BrowserContext > {
395						const context = await target.newContext( {
396							...options,
397							...config.contextOptions,
398							recordVideo: { dir: os.tmpdir() },
399						} );
400	
401						await context.tracing.start( {
402							screenshots: true,
403							snapshots: true,
404						} );
405	
406						return context;
407					};
408				}
409	
410				if ( prop === 'newPage' ) {
411					return async function ( options: BrowserContextOptions ): Promise< Page > {
412						const page = await target.newPage( {
413							...options,
414							...config.contextOptions,
415							recordVideo: { dir: os.tmpdir() },
416						} );
417	
418						// Set the default timeout for all Playwright methods.
419						// Default value is 15000ms, defined in env-variables.ts.
420						page.setDefaultTimeout( env.TIMEOUT );
421	
422						// Set up a HTTP response status interceptor
423						// to capture instances of 502 Bad Gateway.
424						// This remains active until the page is
425						// closed.
426						page.on( 'response', async ( response ) => {
427							if ( response.status() === 502 ) {
428								await page.reload();
429							}
430						} );
431	
432						// Add route abort for slow requests on AT sites.
433						await page.route( /store\/v1\/cart/, ( route ) => {
434							route.abort();
435						} );
436						await page.route( /rest\/v1\/batch/, ( route ) => {
437							route.abort();
438						} );
439						await page.route( /pubmine/, ( route ) => {
440							route.abort();
441						} );
442	
443						const context = page.context();
444	
445						await context.tracing.start( {
446							screenshots: true,
447							snapshots: true,
448						} );
449	
450						return page;
451					};
452				}
453	
454				return orig.bind( target );
455			},
